Translate("ruRU", "stonetalon-mountains", {
	title = "Когтистые горы",
	sections = {
		{
			title = "Обзор",
			text = [=[Когтистые горы — стена серых вершин и глубоких зеленых долин на западе {link:kalimdor}Калимдора{/link}, между лесами {link:ashenvale}Ясеневого леса{/link} на севере и равнинами {link:mulgore}Мулгора{/link} и {link:the-barrens}Степей{/link} на юге и востоке. Венчает их {link:stonetalon-peak}Пик Каменного Когтя{/link} — вершина, которую друиды {link:night-elves}ночных эльфов{/link} издавна почитают священной. Ниже земля спускается к озерам, ущельям и лесам исполинских деревьев. Многих из этих деревьев уже нет. {link:venture-company}Торговая Компания{/link} пришла в Когтистые горы с пилами и огнем, и там, где прошли ее машины, духи земли кричат от боли.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, как поднялись эти горы и кто первым дал им имя. Известно лишь, что Когтистые горы были святым местом задолго до того, как в {link:kalimdor}Калимдор{/link} пришли младшие народы. Друиды {link:night-elves}калдореи{/link} построили высоко на пике Пещеру Когтей и хранили в ней свои сокровища. Среди камней вершины лежат руины еще более древнего творения — храма времен, когда правила {link:queen-azshara}королева Азшара{/link}; его строителей помнят немногие, а оплакивают и того меньше. Лес, что одевал долины внизу, был вверен сыновьям и дочерям полубога Кенария, и рос он нетронутым дольше, чем способен счесть любой смертный.

В {link:third-war}Третью войну{/link} пик вошел в историю младших народов. Именно в Когтистые горы {link:cairne-bloodhoof}Кэрн Кровавое Копыто{/link} послал молодого вождя {link:thrall}Тралла{/link} на поиски Оракула, обитавшего в горе. Там вожди {link:horde}Орды{/link} и люди {link:lordaeron}Лордерона{/link} встретили пророка, который призвал их на запад, и узнали, что это {link:medivh}Медив{/link}.]=],
		},
		{
			title = "Наши дни",
			text = [=[Когтистые горы — земля, которая воюет сама с собой. Гоблины Торговой Компании обрушились на леса Утеса Ветрорезов, и их крошшеры за час валят то, что росло тысячу лет. Когда они вторглись в Обугленную долину, что-то в долине дало им отпор, и гоблины, отступая, сожгли ее. Теперь по пеплу бродят элементали огня. {link:harpies}Гарпии{/link} Кровавой Ярости свили гнезда среди почерневших холмов и оттуда расселяются по всему материку.

Ни {link:alliance}Альянс{/link}, ни {link:horde}Орда{/link} не оставят эти горы. {link:night-elves}Ночные эльфы{/link} держат {link:stonetalon-peak}Пик Каменного Когтя{/link}, а на краю Утеса Ветрорезов Часовая и маг-{link:gnomes}гном{/link} вместе действуют против гоблинов. Орда держит {link:sun-rock-retreat}Приют у Солнечного Камня{/link} в сердце хребта, где {link:tauren}таурен{/link}ы и {link:orcs}орк{/link}и стараются исцелить землю. В {link:malaka-jin}Малака'джин{/link}е, на дальнем юге, {link:darkspear-trolls}тролли Черного Копья{/link} охотятся и варят зелья. На юго-востоке собственный военный лагерь разбил {link:grimtotem-clan}клан Зловещего Тотема{/link}. Все они согласны в одном: {link:venture-company}Торговая Компания{/link} должна уйти. Больше они почти ни в чем не согласны.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}Калдореи пика.{/b} Друиды и {link:sentinels}Часовые{/link} хранят {link:stonetalon-peak}Пик Каменного Когтя{/link} и Пещеру Когтей. Их мало, и они бдительны.
• {b}{link:horde}Орда{/link} Солнечного Камня.{/b} {link:tauren}Таурены{/link}, {link:orcs}орк{/link}и и те, кто пришел сражаться рядом с ними, держат {link:sun-rock-retreat}Приют у Солнечного Камня{/link} — единственный надежный кров между Степями и {link:desolace}Пустошами{/link}.
• {b}{link:venture-company}Торговая Компания{/link}.{/b} Гоблины — лесорубы, рудокопы и инженеры — разрабатывают {link:windshear-crag}Утес Ветрорезов{/link} при помощи {link:ogres}огр{/link}омных машин, а стерегут их наемники.
• {b}{link:harpies}Гарпии{/link} Кровавой Ярости.{/b} Они гнездятся в Обугленной долине, и их королева правит ими с западных холмов долины.
• {b}{link:grimtotem-clan}Клан Зловещего Тотема{/link}.{/b} Военный отряд этого клана тауренов держит Заставу Зловещего Тотема на юго-востоке и совершает набеги на деревни собственного народа.
• {b}Кобольды, пауки и виверны.{/b} {link:kobolds}Кобольды{/link} роют глубины Ущелья Камнепадов. Огромные пауки по ночам охотятся на Паучьем тракте. Виверны {link:gordo}Гордо{/link}го Крыла гнездятся на высоких утесах.
• {b}{link:trolls}Тролли{/link} {link:malaka-jin}Малака'джин{/link}а.{/b} Деревня племени Черного Копья стоит у южного подножия гор, там, где дорога поднимается из Степей.]=],
		},
		{
			title = "История",
			text = [=[• {b}Век друидов.{/b} Несчетные века Когтистые горы принадлежали лесу и тем, кто его охранял. Друиды пика и дети полубога Кенария берегли зелень долин.
• {b}Оракул.{/b} В Третью войну {link:thrall}Тралл{/link} пришел в Когтистые горы на поиски Оракула, и там пророк {link:medivh}Медив{/link} призвал {link:orcs}орк{/link}ов и людей объединиться перед пришествием {link:burning-legion}Пылающего Легиона{/link}.
• {b}Приход Орды.{/b} После {link:battle-of-mount-hyjal}битвы у горы Хиджал{/link} {link:horde}Орда{/link} и {link:tauren}таурен{/link}ы обрели дом в {link:kalimdor}Калимдор{/link}е. В горах был возведен {link:sun-rock-retreat}Приют у Солнечного Камня{/link}, а племя Черного Копья поселилось в {link:malaka-jin}Малака'джин{/link}е. Ни одна летопись не называет года ни того, ни другого.
• {b}Нашествие гоблинов.{/b} {link:venture-company}Торговая Компания{/link} пришла в горы рубить лес и добывать руду. Она оголила {link:windshear-crag}Утес Ветрорезов{/link}, сожгла Обугленную долину и отравила духов земли.
• {b}Наши дни.{/b} Друиды, шаманы, {link:sentinels}Часовые{/link} и {link:gnomes}гном{/link}ы сражаются теперь, чтобы исцелить то, что разрушили гоблины. Гоблины дают отпор, а гарпии, клан Зловещего Тотема и духи огня воюют со всеми.]=],
		},
		{
			title = "Предания гор",
			text = [=[• Шаманы говорят, что духи Когтистых гор почти ослепли от боли и ярости. Те, кто умеет слушать, слышали, как кричит сама земля.
• Говорят, что гарпии Кровавой Ярости — источник гарпийской напасти по всему {link:kalimdor}Калимдор{/link}у. {link:harpies}Гарпии{/link} Ведьминого Крыла из Степей пришли из этих гор.
• Высоко на пике некогда жил один из старших сыновей полубога Кенария. Звали его {link:keeper-ordanus}Орданус{/link}, и его тайно увезли, когда враг вышел на охоту за ним.
• Говорят, что семена Геи с Мутного озера не поддаются порче. {link:tauren}Таурены{/link} сажают их в пепел Обугленной долины в надежде, что однажды там поднимется новый лес.
• Под Ущельем Камнепадов {link:kobolds}кобольд{/link}ы нашли кристалл, который называют Резонитом. Там, где он лежал, спало нечто более древнее, чем кобольды.]=],
		},
	},
})

Translate("ruRU", "stonetalon-peak", {
	title = "Пик Каменного Когтя",
	sections = {
		{
			title = "Обзор",
			text = [=[Пик Каменного Когтя — венец гор, высокая зеленая вершина на дальнем северо-западе хребта. {link:night-elves}Ночные эльфы{/link} хранят его веками, и в наши дни за ним присматривает хранитель {link:keeper-albagorm}Альбагорм{/link} с горсткой друидов, Часовых и дружественных древней. Тех, кто добрался сюда, принимает небольшая таверна, а гипп{link:ogres}огр{/link}ифы несут вести в {link:ashenvale}Ясеневый лес{/link} и дальше. Пик свят для калдореи, но таит и более древние и странные вещи: руины храма времен, когда правила {link:azshara}Азшара{/link}, и хранилища Пещеры Когтей. Именно отсюда {link:keeper-ordanus}Орданус{/link}а, сына полубога Кенария, увезли в безопасное место.]=],
		},
	},
})

Translate("ruRU", "the-talon-den", {
	title = "Пещера Когтей",
	sections = {
		{
			title = "Обзор",
			text = [=[Пещера Когтей лежит в высоких западных лощинах Пика Каменного Когтя. Друиды построили ее, чтобы хранить предметы силы, и придумали хитроумный порядок, чтобы эти сокровища не попали в дурные руки: ключ, спрятанный в фонаре у входа, тайники, разбросанные по пещере, и главный клад, который открывается только тремя ключами сразу. Ее и поныне охраняют друиды {link:krueg-skullsplitter}Круг{/link}а Кенария, а с ними привратник, ключник, дриады и хранители Мутного озера. Среди деревьев над ней видели редкого волшебного дракончика по имени Нал'тасзар.]=],
		},
	},
})

Translate("ruRU", "sun-rock-retreat", {
	title = "Приют у Солнечного Камня",
	aliases = { "Солнечный Камень" },
	sections = {
		{
			title = "Обзор",
			text = [=[Приют у Солнечного Камня — оплот {link:horde}Орды{/link} в сердце Когтистых гор. Он стоит на скальном возвышении посреди хребта, под охраной {link:orcs}орк{/link}ов-рубак, и ведут к нему извилистые дороги из Степей и Пустошей. Его предводители — большей частью {link:tauren}таурен{/link}ы. Обороной командует {link:maggran-earthbinder}Маггран Связующий Землю{/link}. {link:tammra-windfield}Таммра Ветреное Поле{/link} и {link:mor-rogal}Мор'рогал{/link} заботятся об израненной земле, а дух воды по имени {link:tsunaman}Цунаман{/link} ведет собственную войну против огня. Таверна, пост ветрокрылов и горстка торговцев делают Приют местом, где путники могут отдохнуть. Здесь же Орда собирает силы против гарпий, гоблинов и клана Зловещего Тотема.]=],
		},
	},
})

Translate("ruRU", "windshear-crag", {
	title = "Утес Ветрорезов",
	sections = {
		{
			title = "Обзор",
			text = [=[Утес Ветрорезов — большая восточная долина Когтистых гор и место, где {link:venture-company}Торговая Компания{/link} натворила худших бед. Там, где некогда стоял старый лес, склоны теперь покрыты пнями. Вдоль ручьев выстроились лесопилки и водяные колеса, а между деревьями шагают крошшеры XT:4 и XT:9. Глубоко в холмах гоблины и наемные рудокопы добывают в Руднике Ветрорезов странную золотисто-зеленую руду. Где-то в долине компания держит небольшой воздушный порт для своих летающих машин. На западном краю утеса вместе несут дозор Часовая ночных эльфов и маг-{link:gnomes}гном{/link}, а неподалеку от них гоблин-инженер, прежде служивший компании, строит козни против бывших хозяев.]=],
		},
	},
})

Translate("ruRU", "cragpool-lake", {
	title = "Скалистое озеро",
	sections = {
		{
			title = "Обзор",
			text = [=[Скалистое озеро лежит на севере Утеса Ветрорезов. Его берега стали сердцем работ Торговой Компании в Когтистых горах. К югу от озера стоит лесопилка, где компания хранит свои инженерные чертежи. Высоко над водой, возле {link:ogres}огр{/link}омного водяного колеса, за всей разработкой надзирает {link:gnomes}гном{/link} {link:gerenzo-wrenchwhistle}Геренцо Гайкосвист{/link}. Путники из Ясеневого леса, которые спускаются через {link:the-talondeep-path}Туннель Когтя{/link}, должны пройти мимо озера по пути на юго-запад, к пику.]=],
		},
	},
})

Translate("ruRU", "mirkfallon-lake", {
	title = "Мутное озеро",
	sections = {
		{
			title = "Обзор",
			text = [=[Мутное озеро — большое круглое озеро посреди горного прохода, к северу от Приюта у Солнечного Камня. У его вод растут два примечательных растения. Первое — семя Геи, которое находят у самой кромки воды; {link:tauren}таурен{/link}ы дорожат им, потому что оно не поддается порче и может вернуть жизнь загубленной земле. Второе — мракотрав, чьи стручки, высохнув, становятся ярко-красными и дают отличный пигмент для краски. Озеро красиво и дико, и тем, кто собирает его дары, надо остерегаться зверей, что приходят туда на водопой.]=],
		},
	},
})

Translate("ruRU", "the-charred-vale", {
	title = "Обугленная долина",
	aliases = { "Долина Кровавой Ярости" },
	sections = {
		{
			title = "Обзор",
			text = [=[Обугленная долина лежит на западе гор, к югу от Пика Каменного Когтя. Когда-то это был пышный лес. Когда {link:venture-company}Торговая Компания{/link} вторглась в него, стражи долины отбросили ее, и гоблины, убегая, подожгли лес. Их оружие осквернило древней, которые с ними сражались, а огонь выпустил на волю пылающих духов пламени, камня и ярости. Теперь долина — пепел и дым. {link:harpies}Гарпии{/link} Кровавой Ярости гнездятся в ее холмах, в Долине Кровавой Ярости, и их королева держит западные гряды. И {link:night-elves}калдореи{/link}, и {link:tauren}таурен{/link}ы мечтают снова сделать ее зеленой.]=],
		},
	},
})

Translate("ruRU", "greatwood-vale", {
	title = "Долина Высокого леса",
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Высокого леса лежит на юго-востоке Когтистых гор, там, где дорога от Перекрестка поднимается из Степей в горы. Ее имя напоминает об исполинских деревьях, которыми она полна. Шаманка Орды {link:seereth-stonebreak}Сирет Камнелом{/link} разбила лагерь близ долины, когда ее послали ответить на крики земли, и именно от края долины тропа уходит на северо-запад, к Утесу Ветрорезов — прямо в зубы Торговой Компании.]=],
		},
	},
})

Translate("ruRU", "webwinder-path", {
	title = "Паучий тракт",
	aliases = { "Сиширский каньон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Паучий тракт — длинная дорога через южные долины Когтистых гор, которая соединяет {link:sun-rock-retreat}Приют у Солнечного Камня{/link} с {link:malaka-jin}Малака'джин{/link}ом и Степями. Свое имя он получил от пауков, которые его облюбовали. Гуще всего их в Сиширском каньоне, к западу от дороги, где {link:ogres}огр{/link}омная паучиха {link:besseleth}Бесселет{/link} и ее выводок устроили затянутое паутиной логово. По ночам они выходят на охоту, и путники, которые идут по тракту после заката, не всегда добираются до его конца. Даже тролли Малака'джина, которые мало чего боятся, держатся у своих костров, когда солнце село.]=],
		},
	},
})

Translate("ruRU", "malaka-jin", {
	title = "Малака'джин",
	sections = {
		{
			title = "Обзор",
			text = [=[Малака'джин — деревня троллей у южного подножия Когтистых гор, там, где дорога поднимается из Степей. Ее жители — {link:darkspear-trolls}тролли Черного Копья{/link}, и они разбогатели здесь на обильной охоте в холмах. Деревня славится целебными отварами и знахарями, прежде всего это {link:witch-doctor-jin-zil}Джин'Зил{/link}, который держит в клетках возле своей хижины трех пленных ночных эльфов. По ночам на лагерь нападают пауки, и охотники деревни хотят от них избавиться. {link:grimtotem-post}Застава Зловещего Тотема{/link} лежит недалеко к северу.]=],
		},
	},
})

Translate("ruRU", "boulderslide-ravine", {
	title = "Ущелье Камнепадов",
	aliases = { "Пещера Камнепадов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ущелье Камнепадов — глубокая теснина на юге Когтистых гор, к юго-востоку от Приюта у Солнечного Камня. В его стене открывается пещера, и в этой пещере {link:kobolds}кобольды{/link}, которых ведет Гоггер Камнедробитель, лихорадочно роют землю в поисках редкого кристалла — Резонита. На дне своих туннелей они нашли не только кристалл. В глыбе из кристаллов Резонита лежал {link:goggeroc}Гоггерок{/link} — земельник, спавший с незапамятных времен. Шаманы Солнечного Камня числят это среди самых грозных опасностей гор.]=],
		},
	},
})

Translate("ruRU", "grimtotem-post", {
	title = "Застава Зловещего Тотема",
	aliases = { "Лагерь Апарахе" },
	sections = {
		{
			title = "Обзор",
			text = [=[Застава Зловещего Тотема — военный лагерь {link:grimtotem-clan}клана Зловещего Тотема{/link} на юго-востоке Когтистых гор, над дорогой в {link:burning-steppes}Степи{/link}. Отсюда {link:grundig-darkcloud}Грундиг Темная Туча{/link} и его громилы напали на деревню {link:tauren}таурен{/link}ов и перебили почти всех ее жителей. Девушку по имени {link:kaya-flathoof}Кайя Плоское Копыто{/link} увели в лагерь пленницей. Поблизости лежит Лагерь Апарахе. Именно туда Кайя попросила отвести ее, когда ее освободили, ибо оттуда она знала дорогу домой.]=],
		},
	},
})

Translate("ruRU", "the-talondeep-path", {
	title = "Туннель Когтя",
	sections = {
		{
			title = "Обзор",
			text = [=[Туннель Когтя — проход сквозь горы, который соединяет северо-восток Когтистых гор с югом Ясеневого леса, неподалеку от Озера Мистраль. Это дорога {link:night-elves}калдореи{/link}, которые идут на юг, к пику, и всякого путника, который предпочел бы не пересекать {link:burning-steppes}Степи{/link}. У выхода в {link:stonetalon-mountains}Когтистые горы{/link}, над Утесом Ветрорезов, держит свой лагерь шаман Орды {link:braug-dimspirit}Брауг Тусклый Дух{/link} и испытывает мудрость тех, кто к нему приходит.]=],
		},
	},
})

Translate("ruRU", "keeper-albagorm", {
	title = "Хранитель Альбагорм",
	subtitle = "Хранитель Пика Каменного Когтя",
	found = "Пик Каменного Когтя",
	hint = [=[Поднимитесь на венец гор и поговорите с хранителем, который за ним присматривает.]=],
	allegiance = "Дарнасс · друиды пика",
	aliases = { "Альбагорм" },
	sections = {
		{
			title = "Обзор",
			text = [=[Хранитель Альбагорм — страж Пика Каменного Когтя из народа {link:night-elves}калдореи{/link}. Он называет себя защитником лесных духов, и с вершины он видел, как леса внизу гибнут от огня и пилы. Он не плакал. Он строил замысел. Его ответ на гибель Обугленной долины — не одна лишь месть, но возрождение, и он намерен увидеть долину снова зеленой.]=],
		},
		{
			title = "Значение",
			text = [=[Альбагорм — голос старой веры {link:night-elves}калдореи{/link} в Когтистых горах. Землю он видит единым живым существом, а гоблинов и гарпий — ранами на ней. Он знает и то, что друидам пика не исцелить ее в одиночку, и просит помощи у друидов даже в далеком {link:feralas}Фераласе{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он несет стражу над Пиком Каменного Когтя и друидами, которые там живут.
• Он посылает путников против гарпий Кровавой Ярости, которые не пускают друидов в Обугленную долину.
• Он ищет помощи друида Фалфинделя Стража Путей из {link:feralas}Фералас{/link}а, который способен призвать в загубленную долину великих духов леса.
• Он принимает путников, которых духи леса присылают к нему из Ясеневого леса.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна летопись не говорит, как давно Альбагорм хранит пик и чем он занимался до прихода гоблинов.]=],
		},
	},
	chapters = {
		{
			title = "Поругание долины",
			hint = "Откликнитесь на призыв хранителя очистить Обугленную долину.",
			text = [=[Альбагорм называет причину гибели Обугленной долины прямо: жадность. Машины гоблинов подожгли долину, и теперь гарпии Кровавой Ярости сидят на ее пепле и гонят прочь любого друида, который приходит сажать заново. Прежде чем долину можно будет исцелить, гарпий надо изгнать. Пощады для них он не просит.]=],
		},
		{
			title = "Призыв в Фералас",
			hint = "Отнесите мольбу хранителя далеко на юг.",
			text = [=[{link:harpies}Гарпии{/link} разбиты, но они вернутся. Альбагорм знает, что одним семенам их не опередить. Он шлет весть через весь {link:kalimdor}Калимдор{/link} друиду Фалфинделю Стражу Путей, на край лесов {link:feralas}Фералас{/link}а. Хранитель верит, что только великие духи леса успеют вернуть долину.]=],
		},
	},
	mentions = {
		{
			text = [=[Путь к Пику Каменного Когтя: посылает друид {link:faldreas-goeth-shael}Фалдреас{/link}]=],
		},
		{ text = "Возвращение Обугленной долины" },
		{ text = "Возвращение Обугленной долины: призыв к друиду Фалфинделю" },
	},
	bonds = {
		{ id = "kaela-shadowspear", name = "Каэла Копье Теней", note = "сражается с тем же врагом на Утесе Ветрорезов" },
		{ id = "bloodfury-ripper", name = "Потрошительница из стаи Кровавой Ярости", note = "королева гарпий, которых он хочет изгнать" },
		{ id = "braelyn-firehand", name = "Брейлин Огненная Рука", note = "охотится на друидов его пика" },
	},
})

Translate("ruRU", "kaela-shadowspear", {
	title = "Каэла Копье Теней",
	subtitle = "Часовая Когтистых гор",
	found = "Смотровая площадка на западном краю Утеса Ветрорезов",
	hint = [=[Найдите Часовую, которая смотрит на долину у входа на Утес Ветрорезов.]=],
	allegiance = "Часовые · Дарнасс",
	aliases = { "Каэла" },
	sections = {
		{
			title = "Обзор",
			text = [=[Каэла Копье Теней — Часовая из Ясеневого леса, посланная в {link:stonetalon-mountains}Когтистые горы{/link} узнать, что происходит с землей. Она увидела леса Утеса Ветрорезов вырубленными, а Обугленную долину — в огне. С тех пор она остается здесь и сражается с гоблинами со смотровой площадки над утесом. Рядом с ней трудится маг-{link:gnomes}гном{/link} {link:gaxim-rustfizzle}Гаксим Ржавошип{/link}, и ее собственному народу трудно поверить в такой союз.]=],
		},
		{
			title = "Значение",
			text = [=[Каэла — свидетельство того, как далеко зашла беда. Ночная эльфийка и {link:gnomes}гном{/link}, Часовая, которая не доверяет тайной магии, и маг, который ею упивается, подали друг другу руки против общего врага. Каэла просит других не судить о гноме слишком поспешно. Уже то, что она способна так сказать, — знамение времени.]=],
		},
		{
			title = "Деяния",
			text = [=[• В {link:stonetalon-mountains}Когтистые горы{/link} ее послали по приказу Часовой Волчьей Бегуньи, и ее подруга {link:sentinel-thenysil}Тара Тенисил{/link} в {link:astranaar}Астранаар{/link}е давно ждет от нее вестей.
• Она борется с тем, как {link:venture-company}Торговая Компания{/link} губит леса.
• Она охотится на пылающих духов, вырвавшихся на волю в Обугленной долине.
• Она извлекает осколки из раненых древней долины, чтобы {link:gaxim-rustfizzle}Гаксим{/link} узнал, как их осквернили.]=],
		},
	},
	chapters = {
		{
			title = "Плачущая долина",
			hint = "Помогите Часовой против пылающих духов Обугленной долины.",
			text = [=[Когда Каэла впервые увидела Обугленную долину, она едва не заплакала. Гоблины не просто сожгли деревья. В своем безрассудстве они выпустили на волю элементалей пламени, камня и ярости, и пока эти духи бродят по долине, говорит она, земле не увидеть улыбки богини Элуны.]=],
		},
		{
			title = "Весть в Астранаар",
			hint = "Доставьте новости Часовой домой, в Ясеневый лес.",
			text = [=[Когда гоблинам нанесен удар, Каэла наконец шлет весть на север: она и {link:gaxim-rustfizzle}Гаксим{/link} живы и уже близки к тому, чтобы остановить Торговую Компанию. В {link:astranaar}Астранаар{/link}е {link:sentinel-thenysil}Тара Тенисил{/link} слышит эту новость и радуется, и не только за подругу. Она ловит себя на том, что рада и за {link:gnomes}гном{/link}а.]=],
		},
	},
	mentions = {
		{
			text = [=[На страже в Когтистых горах: посылает {link:sentinel-thenysil}Часовая Тенисил{/link}]=],
		},
		{ text = "На страже в Когтистых горах" },
		{ text = "Разъяренные духи" },
		{ text = "Раненые древние" },
		{
			text = [=[Вести для Часовой: принесены от {link:gnomes}гном{/link}а {link:gaxim-rustfizzle}Гаксим{/link}а]=],
		},
		{ text = "Вести для Часовой {link:sentinel-thenysil}Тенисил{/link}" },
	},
	bonds = {
		{ id = "gaxim-rustfizzle", name = "Гаксим Ржавошип", note = "ее неожиданный напарник" },
		{ id = "keeper-albagorm", name = "хранитель Альбагорм", note = "охраняет пик над ней" },
		{ id = "tyrande-whisperwind", name = "Тиранда Шелест Ветра", note = "слышит о ее задании" },
	},
})

Translate("ruRU", "gaxim-rustfizzle", {
	title = "Гаксим Ржавошип",
	subtitle = "Гном из Просвещенного собрания",
	found = [=[Рядом с Часовой Каэлой Копьем Теней, на западном краю Утеса Ветрорезов]=],
	hint = [=[Найдите гнома, который трудится рядом с Часовой над Утесом Ветрорезов.]=],
	allegiance = [=[Изгнанники Гномрегана · Просвещенное собрание арканологии, алхимии и инженерных наук]=],
	aliases = { "Гаксим" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гаксим Ржавошип — {link:gnomes}гном{/link}, маг и механик, и гордый член ученого общества с очень длинным названием: Просвещенное собрание арканологии, алхимии и инженерных наук. В {link:stonetalon-mountains}Когтистые горы{/link} он пришел вместе с Часовой Каэлой Копьем Теней. Он верит всей силой своего маленького тела, что сплав магии, смесей и механизмов способен спасти леса ночных эльфов. Доказать это он намерен взрывчаткой.]=],
		},
		{
			title = "Значение",
			text = [=[Гаксим воплощает мысль, которой {link:night-elves}калдореи{/link} давно противятся: что магия и ремесло, если применять их с умом, могут служить лесу, а не вредить ему. Он открыто говорит, что ночным эльфам нужна магия и что она нужна миру. Его война с Торговой Компанией — это его довод.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он теснит гоблинов меткими взрывами вдоль края гор.
• Он создает взрывчатку, которую можно подорвать издалека, из редкого состава NG-5 и заклинания для передачи сообщений.
• Он замышляет два налета на Торговую Компанию: один за ее инженерными чертежами, другой за ее письмами.
• Он изучает осколки, извлеченные из оскверненных древней Обугленной долины.]=],
		},
	},
	chapters = {
		{
			title = "Взрыв на расстоянии",
			hint = "Соберите то, что нужно гному для его взрывного устройства.",
			text = [=[Для замысла {link:gnomes}гном{/link}у требовались две вещи, которые он не мог сделать сам. Первая — Нитромирглицероний, или NG-5, сварить который умел только его старый коллега Ломак Гирстрип из {link:tinker-town}Города Механиков{/link}. Вторая — заклинание, которое позволило бы подорвать заряд издалека, и ради него он написал магу из {link:stormwind-city}Штормград{/link}а по имени Коллин Морен. Когда то и другое оказалось у него в руках, Гаксим объявил свое устройство совершенным. Повозки с динамитом были готовы.]=],
		},
		{
			title = "Тайные операции",
			hint = "Исполните замыслы гнома против Торговой Компании.",
			text = [=[Дело было вовсе не во взрывах, уверял Гаксим. Они лишь отвлекали внимание. Пока гоблины метались в панике, была взята настоящая добыча: инженерные чертежи с лесопилки к югу от Скалистого озера и личные письма компании. С их помощью Гаксим надеялся найти слабые места гоблинских машин, а заодно, быть может, позаимствовать кое-что из их устройства.]=],
		},
	},
	mentions = {
		{ text = "Передышка {link:gnomes}гном{/link}а" },
		{ text = "Старый коллега" },
		{ text = "Неумелость + химикаты = веселье" },
		{ text = "Свиток от мага Морена" },
		{ text = "Особая посылка для {link:gnomes}гном{/link}а Гаксима" },
		{ text = "Тайные операции — «Альфа»" },
		{ text = "Тайные операции — «Бета»" },
		{ text = "Вести для Часовой" },
		{ text = "Прием у жрицы Тиранды, после налетов" },
		{ text = "Задание инженера Чугунной Трубы" },
	},
	bonds = {
		{ id = "kaela-shadowspear", name = "Каэла Копье Теней", note = "его напарница в Когтистых горах" },
		{ id = "gerenzo-wrenchwhistle", name = "Геренцо Гайкосвист", note = "гном на другой стороне" },
		{ id = "tyrande-whisperwind", name = "Тиранда Шелест Ветра", note = "чествует тех, кто помогает его делу" },
	},
})

Translate("ruRU", "seereth-stonebreak", {
	title = "Сирет Камнелом",
	subtitle = "Шаманка Орды",
	found = "Застава Чести, на границе Степей и Когтистых гор",
	hint = [=[Найдите шаманку, которая стоит лагерем на западной дороге, где Степи поднимаются к Когтистым горам.]=],
	allegiance = "Орда · Оргриммар",
	aliases = { "Сирет" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сирет Камнелом — молодая шаманка {link:horde}Орды{/link}, посланная из {link:orgrimmar}Оргриммар{/link}а ответить на крики Когтистых гор. Старший провидец {link:zor-lonetree}Зор Одинокое Древо{/link} услышал, что земле больно. Узнать причину он послал ее. Она увидела, как гоблины Торговой Компании рубят и жгут леса, и с тех пор стоит лагерем на границе и собирает всю помощь, какую может.]=],
		},
		{
			title = "Значение",
			text = [=[Сирет — первый ответ Орды на беду Когтистых гор. Именно ее слово донесло дело до старейшин {link:tauren}таурен{/link}ов, а через них — до старейшины Магаты {link:grimtotem-clan}Зловещий Тотем{/link} и до {link:forsaken}Отрекшихся{/link}. То, что началось с видения шаманки, обернулось заговором отравителей.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она сообщает в {link:orgrimmar}Оргриммар{/link} о великой вырубке лесов Когтистых гор и просит помощи.
• Она посылает воинов на {link:windshear-crag}Утес Ветрорезов{/link} против гоблинов и их прислужников.
• Ей снятся два крошшера, которые валят деревья утеса.
• Она ищет совета у старейшин {link:tauren}таурен{/link}ов, и прежде всего у ведуньи Магаты.]=],
		},
	},
	chapters = {
		{
			title = "Голос земли",
			hint = [=[Откликнитесь на зов провидца и придите к границе Когтистых гор.]=],
			text = [=[Сирет слышит духов Когтистых гор так, как слышит их шаман, и слышит она ярость. Гоблины отняли деревья, и духи почти ослепли от боли. Терпения она не советует. Она просит показать Торговой Компании единственный язык, который та понимает.]=],
		},
		{
			title = "XT:4 и XT:9",
			hint = "Заставьте замолчать машины из видения шаманки.",
			text = [=[Большая часть шепота духов от нее ускользает, но одно видение было ясным: две человекоподобные машины на Утесе Ветрорезов, которые валят деревья с немыслимой быстротой и помечены знаками XT:4 и XT:9. Когда обе были уничтожены, многие духи успокоились. Сирет не радовалась. Если гоблины не уйдут из гор, предупредила она, худшее еще впереди.]=],
		},
	},
	mentions = {
		{ text = "Духи Когтистых гор" },
		{ text = "Гоблины-захватчики" },
		{ text = "Машины-крошшеры" },
		{ text = "{link:magatha-grimtotem}Старшая Ведунья{/link}" },
	},
	bonds = {
		{ id = "zor-lonetree", name = "Зор Одинокое Древо", note = "послал ее в Когтистые горы" },
		{ id = "magatha-grimtotem", name = "Магата Зловещий Тотем", note = "старейшина, которой она послала весть" },
		{ id = "makaba-flathoof", name = "Макаба Плоское Копыто", note = "делит с ней лагерь" },
	},
})

Translate("ruRU", "maggran-earthbinder", {
	title = "Маггран Связующий Землю",
	subtitle = "Защитник Солнечного Камня",
	found = "Приют у Солнечного Камня",
	hint = [=[Поговорите с тауреном, который командует обороной Приюта у Солнечного Камня.]=],
	allegiance = "Орда · Громовой Утес",
	aliases = { "Маггран" },
	sections = {
		{
			title = "Обзор",
			text = [=[Маггран Связующий Землю — воин-{link:tauren}таурен{/link}, который держит оборону Приюта у Солнечного Камня. Он верит, что его народ — защитник этих земель, и принимает этот долг близко к сердцу. Он носит шрам от клыков паучихи {link:besseleth}Бесселет{/link} и воюет с {link:harpies}гарпия{/link}ми Кровавой Ярости так давно, что не знает, чем займется без них.]=],
		},
		{
			title = "Значение",
			text = [=[Маггран — рука Орды в Когтистых горах. Там, где шаманы исцеляют, он сражается, и награды, которые он назначает, — мерило каждой опасности в горах.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он назначает награды за гарпий Кровавой Ярости и за их королеву.
• Он назначает цену за голову паучихи {link:besseleth}Бесселет{/link} из Сиширского каньона, которая некогда ранила его.
• Он посылает воина из запаса сменить стражника Гриша Дальнего Бегуна у Великого Подъемника, чтобы молодой стражник мог навестить семью.
• Он отправляет солнечные камни гарпий шаману {link:mor-rogal}Мор'рогал{/link}у, которому они пригодятся.]=],
		},
	},
	chapters = {
		{
			title = "Гарпийская напасть",
			hint = [=[Откликнитесь на призыв защитника против гарпий Кровавой Ярости.]=],
			text = [=[Маггран не считает гарпий Кровавой Ярости местной бедой. Для него они источник гарпий, которые терзают весь {link:kalimdor}Калимдор{/link}, — недуг, что расползается из Обугленной долины и держит невинных в плену в ее пределах. Проредить их ряды мало. Лекарство, говорит он, — их королева.]=],
		},
		{
			title = "После королевы",
			hint = "Сразите королеву гарпий Кровавой Ярости.",
			text = [=[Когда королева гарпий, {link:bloodfury-ripper}Потрошительница из стаи Кровавой Ярости{/link}, была убита, гнев покинул его. Это удивило самого воина. Годами зло у границ его земли держало его мысли острыми, а теперь они стихли. Быть может, сказал он, это к добру. Быть может, теперь он сможет обратиться к добру, как и подобает {link:tauren}таурен{/link}у.]=],
		},
		{
			title = "Старая хищница",
			hint = "Покончите с угрозой Сиширского каньона.",
			text = [=[{link:besseleth}Бесселет{/link} — старая охотница этих холмов. Однажды ночью она настигла воина на Паучьем тракте, и он едва спасся от нее. Когда ее не станет, надеется Маггран, больше путников придет к Солнечному Камню, не страшась того, что ждет во тьме.]=],
		},
	},
	mentions = {
		{ text = "{link:harpies}Гарпии{/link} угрожают" },
		{ text = "Род Кровавой Ярости" },
		{ text = "Арахнофобия: с предупреждающего знака в Сиширском каньоне" },
		{ text = "Вызов запаса" },
		{ text = "Побрякушки гарпий Кровавой Ярости" },
	},
	bonds = {
		{ id = "bloodfury-ripper", name = "Потрошительница из стаи Кровавой Ярости", note = "королева, смерти которой он желал" },
		{ id = "besseleth", name = "Бесселет", note = "оставила ему шрам" },
		{ id = "mor-rogal", name = "Мор'рогал", note = "получает солнечные камни" },
		{ id = "tammra-windfield", name = "Таммра Ветреное Поле", note = "служит Солнечному Камню вместе с ним" },
	},
})

Translate("ruRU", "tammra-windfield", {
	title = "Таммра Ветреное Поле",
	subtitle = "Целительница земли",
	found = "Приют у Солнечного Камня",
	hint = [=[Найдите тауренку Солнечного Камня, которая исцеляет землю благословениями Матери-Земли.]=],
	allegiance = "Орда · Громовой Утес",
	aliases = { "Таммра" },
	sections = {
		{
			title = "Обзор",
			text = [=[Таммра Ветреное Поле — {link:tauren}таурен{/link}ка из Приюта у Солнечного Камня, которая поставила себе задачу исцелить {link:stonetalon-mountains}Когтистые горы{/link}. Она верит, что только благословения Матери-Земли способны залечить раны, которые оставили жадность и война. Ее орудия — семена, напевы и терпение. Она также тетя девушки по имени {link:kaya-flathoof}Кайя Плоское Копыто{/link}, которую увел клан Зловещего Тотема и которую семья считала погибшей.]=],
		},
		{
			title = "Значение",
			text = [=[Таммра — другое лицо Орды в Когтистых горах. Там, где воины Солнечного Камня истребляют гарпий, она сажает. Она надеется, что однажды {link:venture-company}Торговая Компания{/link} соберет свои пилы, духи огня утихнут и сама земля вытеснит гарпий.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она собирает семена Геи с Мутного озера и наполняет их шаманской силой.
• Она посылает зачарованные семена, чтобы их посадили в плодородных холмиках Обугленной долины.
• Она слышит весть о том, что ее племянницу спасли от клана Зловещего Тотема.]=],
		},
	},
	chapters = {
		{
			title = "Круг возрождения",
			hint = "Принесите целительнице семена с Мутного озера.",
			text = [=[Семена Геи растут только у самой кромки воды на Мутном озере. Таммра берет их в руки и поет над ними, и семена оживают. Только те, кто чист и верен, говорит она, могут исцелить землю. От семян она не просит ничего, кроме роста.]=],
		},
		{
			title = "Новая жизнь в пепле",
			hint = "Посадите зачарованные семена в сердце разрушения.",
			text = [=[Семена посадили в самой середине пепелища, в Обугленной долине, среди гарпий и пылающих духов. Они устоят перед порчей и станут опорой для другой жизни. Со временем, верит Таммра, они снова сделают {link:stonetalon-mountains}Когтистые горы{/link} лесом. Это будет не скоро. Она и не ждет, что скоро.]=],
		},
		{
			title = "Кайя жива",
			hint = "Принесите целительнице весть, которую она не чаяла услышать.",
			text = [=[После того как клан Зловещего Тотема уничтожил деревню ее родни, Таммра считала, что ее племянница {link:kaya-flathoof}Кайя{/link} потеряна. Когда пришла весть, что девушку освободили и что она жива, Таммра могла только возблагодарить.]=],
		},
	},
	mentions = {
		{ text = "{link:krueg-skullsplitter}Круг{/link} возрождения" },
		{ text = "Новая жизнь" },
		{ text = "{link:kaya-flathoof}Кайя{/link} жива" },
	},
	bonds = {
		{ id = "kaya-flathoof", name = "Кайя Плоское Копыто", note = "ее племянница" },
		{ id = "makaba-flathoof", name = "Макаба Плоское Копыто", note = "отец Кайи" },
		{ id = "maggran-earthbinder", name = "Маггран Связующий Землю", note = "служит Солнечному Камню вместе с ней" },
	},
})

Translate("ruRU", "mor-rogal", {
	title = "Мор'рогал",
	subtitle = "Провидец Солнечного Камня",
	found = "Холмы над Приютом у Солнечного Камня",
	hint = [=[Поднимитесь на холмы над Солнечным Камнем и поговорите с тауреном, который чувствует напряжение в воздухе.]=],
	allegiance = "Орда · Громовой Утес",
	sections = {
		{
			title = "Обзор",
			text = [=[Мор'рогал — шаман-{link:tauren}таурен{/link}, который держится холмов над Приютом у Солнечного Камня. Он чувствует, когда с землей что-то неладно. В последнее время он чувствует это остро. Беда, которую он ощутил, исходила не от гоблинов и не от гарпий, а от чего-то глубоко под горами, там, где рыли {link:kobolds}кобольд{/link}ы Ущелья Камнепадов.]=],
		},
		{
			title = "Значение",
			text = [=[Мор'рогал раскрыл одну из самых грозных угроз Когтистых гор: спящего земельника, создание титанов, п{link:ogres}огр{/link}ебенное в кристаллах Резонита под ущельем. Проснись тот в полной силе, считал шаман, все {link:stonetalon-mountains}Когтистые горы{/link} были бы потеряны.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он посылает искателей в пещеру Ущелья Камнепадов узнать, что добывают {link:kobolds}кобольд{/link}ы.
• По старой легенде он узнает в кристалле Резонита магию земельников.
• Он зачаровывает кристалл Резонита, чтобы расколоть глыбу, в которой был заключен земельник {link:goggeroc}Гоггерок{/link}.
• Он находит применение золотым солнечным камням, которые копят гарпии.]=],
		},
	},
	chapters = {
		{
			title = "Кристалл в глубине",
			hint = "Узнайте, что ищут кобольды в Ущелье Камнепадов.",
			text = [=[Образцы руды принесли из пещеры, и Мор'рогал вертел их в руках, пока не вспомнил. Резонит хранит след магии земельников. Легенды говорят, что земельников создали титаны, чтобы придавать облик самой земле. Если {link:kobolds}кобольд{/link}ы зарылись так глубоко, что нашли Резонит, значит, они зарылись достаточно глубоко, чтобы найти земельника.]=],
		},
		{
			title = "Пробуждение земельника",
			hint = "Разбудите спящего под ущельем, пока он не проснулся сам.",
			text = [=[Помешать пробуждению шаман не мог. Он решил разбудить спящего первым, пока {link:goggeroc}Гоггерок{/link} слаб после долгого сна. Зачарованным кристаллом глыбу раскололи, и земельника сразили прежде, чем к нему вернулась сила. Мор'рогал назвал это деянием, за которое в долгу будет весь {link:kalimdor}Калимдор{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:boulderslide-ravine}Ущелье Камнепадов{/link}" },
		{ text = "Пробуждение земельника" },
		{
			text = [=[Побрякушки гарпий Кровавой Ярости: посылает {link:maggran-earthbinder}Маггран{/link}]=],
		},
	},
	bonds = {
		{ id = "goggeroc", name = "Гоггерок", note = "спящий, которого он боялся" },
		{ id = "maggran-earthbinder", name = "Маггран Связующий Землю", note = "присылает ему солнечные камни" },
	},
})

Translate("ruRU", "braelyn-firehand", {
	title = "Брейлин Огненная Рука",
	subtitle = "Служительница скрытого господина",
	found = "Приют у Солнечного Камня",
	hint = [=[Найдите у Солнечного Камня чужачку, которая ненавидит друидов пика.]=],
	allegiance = "Неизвестно · господин в Джеденаре",
	aliases = { "Брейлин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Брейлин Огненная Рука живет среди Орды в Приюте у Солнечного Камня, но вере {link:tauren}таурен{/link}ов она не друг. Она ненавидит друидов Пика Каменного Когтя, которые, по ее словам, душат ток магии в горах. Сюда ее послал господин, который ждет в {link:jaedenar}Джеденар{/link}е, далеко на севере, и вернуться ей нельзя, пока дело не сделано. О временах, когда правила {link:azshara}Азшара{/link}, она говорит так, словно помнит их.]=],
		},
		{
			title = "Значение",
			text = [=[Брейлин — нить чего-то старого и темного в Когтистых горах. Разрушенный храм на пике она называет «нашим» храмом королевы Азшары. Давным-давно она знала {link:keeper-ordanus}Орданус{/link}а, сына полубога Кенария, и говорит, что он ставил себя выше даже высокорожденных. Кем бы она ни была, она жаждет магии, как другие жаждут хлеба.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она добивается смерти друидов {link:krueg-skullsplitter}Круг{/link}а Кенария и детей полубога Кенария на пике.
• Она охотится на {link:keeper-ordanus}Орданус{/link}а, сына полубога, которого друиды тайно переправили в {link:ashenvale}Ясеневый лес{/link}.
• Она вырывает тайны Пещеры Когтей у пленного друида.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Имя ее господина не записано. Не записано и то, почему {link:horde}Орда{/link} позволяет ей жить у Солнечного Камня.]=],
		},
	},
	chapters = {
		{
			title = "Дырявое ведро",
			hint = "Помогите чародейке ослабить хватку друидов в горах.",
			text = [=[В Когтистых горах, говорит Брейлин, черпать магию — все равно что черпать воду дырявым ведром. Когда друиды и дети полубога Кенария пали, она почувствовала, как поток вернулся, сладкий и стремительный. Калдореи, говорит она, глупцы, раз отвергают его.]=],
		},
		{
			title = "Голова сына леса",
			hint = [=[Найдите сына полубога Кенария, которого друиды от нее спрятали.]=],
			text = [=[Своим взором Брейлин отыскала его: {link:keeper-ordanus}Орданус{/link}, один из старших сыновей лесного бога, укрылся на вершине {link:ogres}огр{/link}омного дерева в Ночных Лесах, в Ясеневом лесу. Друиды увели его с пика прежде, чем она успела до него добраться. Когда ей принесли его голову, она взглянула на нее без жалости. Его голова, сказала она, больше не поднимается так высоко.]=],
		},
		{
			title = "Клад пещеры",
			hint = "Идите за тайной, которую Брейлин вырвала у друида.",
			text = [=[Друиды Пещеры Когтей создали хитроумную головоломку из ключей, чтобы уберечь свои сокровища. Брейлин выпытала ее секрет у одного из них: ключ, спрятанный в фонаре, три тайника и клад в сердце пещеры.]=],
		},
	},
	mentions = {
		{ text = "Наследие полубога Кенария" },
		{ text = "{link:keeper-ordanus}Орданус{/link}" },
		{ text = "Пещера" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "хранитель Альбагорм", note = "хранит пик, который она презирает" },
	},
})

Translate("ruRU", "witch-doctor-jin-zil", {
	title = "Знахарь Джин'Зил",
	subtitle = "Знахарь Малака'джина",
	found = "Его хижина в Малака'джине",
	hint = [=[Найдите знахаря Малака'джина, который держит три клетки возле своей хижины.]=],
	allegiance = "Орда · Племя Черного Копья",
	aliases = { "Джин'Зил" },
	sections = {
		{
			title = "Обзор",
			text = [=[Джин'Зил — тролль-знахарь из {link:malaka-jin}Малака'джин{/link}а. Он весел, жесток и стар в своем ремесле. Возле его хижины стоят три клетки, и в каждой сидит {link:night-elves}ночной эльф{/link}. Он называет их своими маленькими друзьями и намерен сварить им на пробу то, что они зовут лесной магией.]=],
		},
		{
			title = "Значение",
			text = [=[Джин'Зил напоминает, что война между Ордой и {link:night-elves}калдореи{/link} идет не только в Ясеневом лесу. Он также связь с прежними днями. Он помнит время, когда его друг Рокхан отправился с диким мок'натал убивать старшую сестру гарпии Серены Кровавое Перо.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он держит в клетках в {link:malaka-jin}Малака'джин{/link}е трех пленных ночных эльфов.
• Он варит для своих пленников зелье из древесного сока, усов, глаз и чешуи волшебного дракончика.
• От старого друга по имени {link:dar}Дар{/link}сок он узнает, что последняя из рода Кровавого Пера мертва.]=],
		},
	},
	chapters = {
		{
			title = "Лесная магия",
			hint = "Соберите странные составляющие для знахаря.",
			text = [=[Для варева знахарю нужны были сок из Когтистых гор, усы сумеречных бегунов, глаза быстроногих оленей и чешуя волшебного дракончика. Много глаз, настаивал он; их никогда не бывает достаточно. Что зелье сделало с эльфами в клетках, он не сказал. Он лишь обещал, что с ним они почувствуют себя как дома.]=],
		},
		{
			title = "Письмо из Степей",
			hint = "Отнесите письмо старого друга в Малака'джин.",
			text = [=[Джин'Зил много лет не получал вестей от своего друга {link:dar}Дар{/link}сока. Письмо сообщало, что Серена Кровавое Перо мертва — последняя в своем роду. Оно вернуло ему молодость, когда он смотрел, как Рокхан уходит с охотником-мок'натал убивать ее старшую сестру.]=],
		},
	},
	mentions = {
		{ text = "Письмо знахарю Джин'Зилу" },
		{ text = "Лесная магия знахаря Джин'Зила" },
	},
	bonds = {
		{ id = "ken-zigla", name = "Кен'зигла", note = "варит зелья в Малака'джине" },
		{ id = "xen-zilla", name = "Ксен'Зилла", note = "из той же деревни" },
	},
})

Translate("ruRU", "ziz-fizziks", {
	title = "Зиз Физзикс",
	subtitle = "Инженер, сменивший сторону",
	found = "Лагерь на западном краю Утеса Ветрорезов",
	hint = [=[Найдите гоблина-инженера, который стоит лагерем на западном краю Утеса Ветрорезов.]=],
	allegiance = "Союз Механиков · Картель Хитрая Шестеренка",
	aliases = { "Зиз" },
	sections = {
		{
			title = "Обзор",
			text = [=[Зиз Физзикс был когда-то главным инженером работ Торговой Компании в Когтистых горах. Потом компания наняла {link:gnomes}гном{/link}а {link:gerenzo-wrenchwhistle}Геренцо Гайкосвист{/link}а и поставила его во главе. Гоблина уволили. Он был так оскорблен, что упросил гоблина Шипоклапана из {link:ratchet}Кабестан{/link}а найти ему работу в Союзе Механиков, и теперь шпионит за прежними хозяевами из лагеря на краю утеса.]=],
		},
